return (() => {
  try {
    // Obtém os dados
    let dados = $json.data;

    // Se os dados não forem um array, tente normalizar
    if (!Array.isArray(dados)) {
      if (dados && typeof dados === 'object') {
        // Se for um objeto único, coloca dentro de um array
        dados = [dados];
      } else {
        // Caso contrário, retorna um erro
        return [{ mensagem: "Erro: Os dados fornecidos não são válidos para processamento." }];
      }
    }

    // Processa os dados agora normalizados
    const resumo = dados.map(item => {
      // Validações para campos individuais
      const nomeValido = typeof item.Nome === 'string' ? item.Nome.trim() : null;
      const isNomeInvalido = !nomeValido || nomeValido === "?" || nomeValido.toLowerCase() === "desconhecido";
      const nomeUsuario = isNomeInvalido ? "Usuário não identificado" : nomeValido;

      const mensagemRespondida = item["Mensagem respondida"]
        ? `Mensagem Respondida: ${item["Mensagem respondida"]}`
        : "Mensagem Respondida: Nenhuma";

      return `Nome: ${nomeUsuario}, Mensagem: ${item.Mensagem || "Mensagem não disponível"}, ${mensagemRespondida}, Horário: ${item.Horário || "Horário não informado"}`;
    }).join('\n');

    return [{ mensagem: resumo }];
  } catch (error) {
    return [{ mensagem: `Erro ao processar as mensagens: ${error.message}` }];
  }
})();

